-- Keep supervisor assignment and agent self-claim events auditable.
CREATE TABLE TicketAssignmentHistory (MaAssignment BIGINT AUTO_INCREMENT PRIMARY KEY, MaTicket INT NOT NULL, MaAgentCu INT NULL, MaAgentMoi INT NOT NULL, MaNguoiThucHien INT NOT NULL, ThoiGian DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CONSTRAINT FK_AssignmentHistory_Ticket FOREIGN KEY(MaTicket) REFERENCES Ticket(MaTicket), CONSTRAINT FK_AssignmentHistory_PreviousAgent FOREIGN KEY(MaAgentCu) REFERENCES UserAccount(MaUser), CONSTRAINT FK_AssignmentHistory_NewAgent FOREIGN KEY(MaAgentMoi) REFERENCES UserAccount(MaUser), CONSTRAINT FK_AssignmentHistory_Actor FOREIGN KEY(MaNguoiThucHien) REFERENCES UserAccount(MaUser), INDEX IX_AssignmentHistory_TicketTime(MaTicket,ThoiGian)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;